    "ctxApiRefBody": "ctx.ref(val)              — Membuat variabel reaktif\nctx.computed(fn)          — Membuat properti computed\nctx.watch(src, cb)        — Memantau perubahan\nctx.onMounted(fn)         — Saat komponen di-mount\nctx.onUnmounted(fn)       — Saat komponen di-unmount\n\nctx.data.client           — Informasi akun pengguna (reaktif)\nctx.data.token            — Token saat ini (reaktif)\nctx.data.isDark           — Mode gelap (reaktif)\n\nctx.api.get(path, query)  — Permintaan GET\nctx.api.post(path, body)  — Permintaan POST\nctx.api.put(path, body)   — Permintaan PUT\nctx.api.delete(path)      — Permintaan DELETE\n\nctx.formatBytes(bytes)    — Format ukuran file\nctx.formatDate(date)      — Format tanggal\nctx.copyText(text)        — Salin ke clipboard\nctx.elMessage             — Pesan Element Plus\nctx.config                — Konfigurasi portal (PORTAL_CONFIG)\nctx.moduleId              — ID modul saat ini\nctx.moduleTitle           — Judul modul saat ini",
